//! Module: __PROJECT_NAME__ — SPA-first starter (S9). One COMMAND + one READ
//! over the framework ModelStore port, auth-ready via the platform edge
//! (/auth/*), named routes for URL generation, and a web/ SPA shell that
//! consumes the OpenAPI client generated by `keel sdk:openapi`.

use std::sync::Arc;

use keel_context::ExecutionContext;
use keel_foundation::{codes, AppError, ExecutionProfileKind, OperationId, TenantId};
use keel_execution::{
    BoxFuture, ExecutionPlan, ExecutionUnit, MutationRecord, OperationHandler, OutboxMessage,
};
use keel_lifecycle::{BootError, Phase, Provider, ServiceRegistry};
use keel_models::{
    FieldDef, FieldType, ModelDef, ModelRuntime, ModelStore, ModelStoreRef, Record,
};
use serde_json::json;
use uuid::Uuid;

pub const OP_CREATE: &str = "__PROJECT_NAME__.create";
pub const OP_LIST: &str = "__PROJECT_NAME__.list";

pub const EVENT_CREATED: &str = "note.created";

/// The persisted model. Served by the `notes` migration you generate with
/// `keel make:migration` (mirrors this shape field-for-field).
pub fn note_model() -> ModelDef {
    ModelDef::new("Note", "__PROJECT_NAME___notes")
        .tenant_scoped()
        .field(FieldDef::new("id", FieldType::Uuid).required())
        .field(FieldDef::new("tenant_id", FieldType::Uuid).required())
        .field(FieldDef::new("body", FieldType::Text).required())
        .field(
            FieldDef::new("created_at", FieldType::Timestamp)
                .required()
                .with_default("now()"),
        )
        .field(
            FieldDef::new("updated_at", FieldType::Timestamp)
                .required()
                .with_default("now()"),
        )
        .field(FieldDef::new("deleted_at", FieldType::Timestamp))
}

fn from_record(record: &Record) -> Result<(Uuid, String), AppError> {
    let id = record
        .get("id")
        .and_then(|v| v.as_str())
        .and_then(|s| Uuid::parse_str(s).ok())
        .ok_or_else(|| AppError::validation("note record missing id"))?;
    let body = record
        .get("body")
        .and_then(|v| v.as_str())
        .unwrap_or_default()
        .to_string();
    Ok((id, body))
}

/// Domain store over the framework ModelStore port (in-memory for TestKit /
/// degraded boot, PgModelStore in production).
#[derive(Clone)]
pub struct NotesStore {
    backend: Arc<dyn ModelStore>,
    runtime: ModelRuntime,
}

impl NotesStore {
    pub fn new(backend: Arc<dyn ModelStore>) -> Self {
        Self {
            backend,
            runtime: ModelRuntime::new(note_model()),
        }
    }

    #[cfg(test)]
    fn in_memory() -> Self {
        Self::new(Arc::new(keel_models::InMemoryModelStore::new()))
    }

    pub fn create(&self, tenant: TenantId, body: &str) -> Result<Uuid, AppError> {
        if body.trim().is_empty() {
            return Err(AppError::validation("note body is required"));
        }
        let mut input = Record::new();
        input.insert("body".into(), json!(body.trim()));
        let stored = self.runtime.insert(&*self.backend, &input, Some(tenant))?;
        let (id, _) = from_record(&stored)?;
        Ok(id)
    }

    pub fn list(&self, tenant: TenantId) -> Result<Vec<serde_json::Value>, AppError> {
        let page = self
            .runtime
            .list(&*self.backend, Some(tenant), vec![], &[], None)?;
        page.items
            .iter()
            .map(|r| {
                let (id, body) = from_record(r)?;
                Ok(json!({ "id": id.to_string(), "body": body }))
            })
            .collect()
    }
}

/// All operation handlers of this module (host builds a CommandBus from these).
pub fn handlers(store: Arc<NotesStore>) -> Vec<Arc<dyn OperationHandler>> {
    vec![
        Arc::new(CreateHandler::new(store.clone())),
        Arc::new(ListHandler::new(store)),
    ]
}

/// Module provider: binds the domain store to the framework ModelStore port
/// (registered by the Platform phase) and registers the handler bundle.
pub struct ModuleProvider;

impl Provider for ModuleProvider {
    fn name(&self) -> &str {
        "module.__PROJECT_NAME__"
    }
    fn phase(&self) -> Phase {
        Phase::Modules
    }
    fn init(&self, registry: &mut ServiceRegistry) -> Result<(), BootError> {
        let backend = registry.get::<ModelStoreRef>()?;
        let store = Arc::new(NotesStore::new(backend.0.clone()));
        registry.insert("module.__PROJECT_NAME__.store", store.clone())?;
        registry.insert(
            "module.__PROJECT_NAME__.handlers",
            Arc::new(handlers(store)),
        )?;
        Ok(())
    }
}
fn text_field(input: &serde_json::Value, field: &str) -> String {
    input
        .get(field)
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string()
}

fn require_tenant(ctx: &ExecutionContext) -> Result<TenantId, AppError> {
    ctx.tenant
        .as_ref()
        .map(|t| t.id)
        .ok_or_else(|| AppError::validation("tenant context is required"))
}

/// `__PROJECT_NAME__.create` (COMMAND): persist one note.
pub struct CreateHandler {
    plan: ExecutionPlan,
    store: Arc<NotesStore>,
}

impl CreateHandler {
    pub fn new(store: Arc<NotesStore>) -> Self {
        Self {
            plan: ExecutionPlan::new(
                OperationId::from_static(OP_CREATE),
                ExecutionProfileKind::Command,
            )
            .with_capability(OP_CREATE),
            store,
        }
    }
}

impl OperationHandler for CreateHandler {
    fn plan(&self) -> &ExecutionPlan {
        &self.plan
    }

    fn handle(
        &self,
        ctx: Arc<ExecutionContext>,
        input: serde_json::Value,
        unit: &mut dyn ExecutionUnit,
    ) -> BoxFuture<'static, Result<serde_json::Value, AppError>> {
        let outcome = (|| -> Result<serde_json::Value, AppError> {
            let tenant = require_tenant(&ctx)?;
            let body = text_field(&input, "body");
            let id = self.store.create(tenant, &body)?;
            unit.record_mutation(MutationRecord {
                resource_type: "note".into(),
                resource_id: Some(id),
                resource_version: 1,
                before: None,
                after: json!({ "id": id.to_string(), "body": body }),
                stream: None,
            });
            unit.queue_outbox(OutboxMessage {
                event: EVENT_CREATED.into(),
                topic: "__PROJECT_NAME__".into(),
                payload: json!({ "id": id.to_string() }),
            });
            Ok(json!({ "id": id.to_string() }))
        })();
        Box::pin(async move { outcome })
    }
}

/// `__PROJECT_NAME__.list` (READ): list the tenant's notes.
pub struct ListHandler {
    plan: ExecutionPlan,
    store: Arc<NotesStore>,
}

impl ListHandler {
    pub fn new(store: Arc<NotesStore>) -> Self {
        Self {
            plan: ExecutionPlan::new(
                OperationId::from_static(OP_LIST),
                ExecutionProfileKind::Read,
            )
            .with_capability(OP_LIST),
            store,
        }
    }
}

impl OperationHandler for ListHandler {
    fn plan(&self) -> &ExecutionPlan {
        &self.plan
    }

    fn handle(
        &self,
        ctx: Arc<ExecutionContext>,
        _input: serde_json::Value,
        _unit: &mut dyn ExecutionUnit,
    ) -> BoxFuture<'static, Result<serde_json::Value, AppError>> {
        let outcome = (|| -> Result<serde_json::Value, AppError> {
            let tenant = require_tenant(&ctx)?;
            Ok(json!({ "notes": self.store.list(tenant)? }))
        })();
        Box::pin(async move { outcome })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use keel_context::{PrincipalContext, ScopeSnapshot, TenantContext};
    use keel_foundation::{AuthorizationRevision, FeatureRevision, ModuleRevision, PrincipalId};
    use keel_execution::{Engine, InMemoryBackend, InMemoryIdempotency};
    use keel_policy::{AccessSnapshot, PolicyAuthz, PolicyEngine};
    use time::OffsetDateTime;

    fn fixture(capabilities: &[&str]) -> (Arc<Engine>, Arc<NotesStore>, PrincipalId, TenantId) {
        let principal = PrincipalId::new();
        let tenant = TenantId::new();
        let policies = Arc::new(PolicyEngine::new());
        policies.install_snapshot(AccessSnapshot {
            principal_id: principal,
            tenant_id: tenant,
            membership_active: true,
            capabilities: capabilities.iter().map(|c| c.to_string()).collect(),
            scope_paths: ["/".to_string()].into_iter().collect(),
            authorization_revision: policies.revision(),
            feature_revision: FeatureRevision(1),
            module_revision: ModuleRevision(1),
            computed_at: OffsetDateTime::now_utc(),
        });
        let engine = Arc::new(Engine::new(
            Arc::new(PolicyAuthz { engine: policies }),
            Arc::new(InMemoryBackend::new()),
            Arc::new(InMemoryIdempotency::new()),
        ));
        (
            engine,
            Arc::new(NotesStore::in_memory()),
            principal,
            tenant,
        )
    }

    fn ctx(principal: PrincipalId, tenant: TenantId) -> Arc<ExecutionContext> {
        ExecutionContext::builder(ExecutionProfileKind::Command, OffsetDateTime::now_utc())
            .principal(PrincipalContext {
                id: principal,
                display: Some("starter-test".into()),
            })
            .tenant(TenantContext {
                id: tenant,
                slug: "starter".into(),
                plan: "standard".into(),
            })
            .scope(ScopeSnapshot {
                nodes: vec![],
                revision: AuthorizationRevision(1),
                computed_at: OffsetDateTime::now_utc(),
            })
            .build()
            .unwrap()
    }

    #[tokio::test]
    async fn create_then_list_roundtrips() {
        let (engine, store, principal, tenant) = fixture(&[OP_CREATE, OP_LIST]);
        let context = ctx(principal, tenant);
        engine
            .execute(
                context.clone(),
                &CreateHandler::new(store.clone()),
                json!({ "body": "first note" }),
                None,
            )
            .await
            .expect("create succeeds");
        let outcome = engine
            .execute(context, &ListHandler::new(store.clone()), json!({}), None)
            .await
            .expect("list succeeds");
        let notes = outcome.result["notes"].as_array().unwrap();
        assert_eq!(notes.len(), 1);
        assert_eq!(notes[0]["body"], "first note");
    }

    #[tokio::test]
    async fn empty_body_is_rejected() {
        let (engine, store, principal, tenant) = fixture(&[OP_CREATE]);
        let context = ctx(principal, tenant);
        let error = engine
            .execute(
                context,
                &CreateHandler::new(store.clone()),
                json!({ "body": "   " }),
                None,
            )
            .await
            .unwrap_err();
        assert_eq!(error.code, codes::VALIDATION);
    }

    #[test]
    fn manifest_compiles_into_the_platform_graph() {
        let manifest = keel_registry::ModuleManifest::from_toml(include_str!("../module.toml"))
            .expect("manifest parses");
        let graph = keel_registry::PlatformGraph::compile(vec![manifest]).expect("graph compiles");
        assert_eq!(graph.operations.len(), 2);
        assert_eq!(graph.modules[0].routes.len(), 2);
        let url = graph
            .resolve_url("__PROJECT_NAME__", "notes.list", &std::collections::BTreeMap::new())
            .expect("named route resolves");
        assert_eq!(url, "/api/v1/__PROJECT_NAME__/notes");
    }

    /// Test provider registering the in-memory ModelStore carrier.
    struct TestModelStoreProvider;

    impl Provider for TestModelStoreProvider {
        fn name(&self) -> &str {
            "test.model-store"
        }
        fn phase(&self) -> Phase {
            Phase::Platform
        }
        fn init(&self, r: &mut ServiceRegistry) -> Result<(), BootError> {
            r.insert(
                "model.store",
                Arc::new(ModelStoreRef(Arc::new(
                    keel_models::InMemoryModelStore::new(),
                ))),
            )?;
            Ok(())
        }
    }

    #[tokio::test]
    async fn provider_boots_with_the_model_store_port() {
        let mut host = keel_lifecycle::ApplicationHost::new();
        host.add_provider(Box::new(TestModelStoreProvider));
        host.add_provider(Box::new(ModuleProvider));
        host.boot().await.expect("module boots");
        let bundle = host
            .registry()
            .get::<Vec<Arc<dyn OperationHandler>>>()
            .expect("handlers registered");
        assert_eq!(bundle.len(), 2);
    }
}